message :    "Benchmark completed successfully"  .  to_string  (  )  ,
throughput_summary :    format!  (  "Processed 12.7M records in 2.8s → {:.0} rows/sec"  ,   throughput )  ,
}  )
}


fn    api_router  (  )    ->    Router    {
Router  ::  new  (  )
.  route  (  "/"  ,    get  (  health )  )
